# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_already_on_step(self):
        spans = [Span(540, 1035)]
        got = round_labels(spans, 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest(self):
        spans = [Span(543, 1030)]
        got = round_labels(spans, 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        got = round_labels([Span(61, 121)], 2)
        self.assertEqual(got, ["01:02-02:02 (1h 0m)"])

    def test_many_spans(self):
        spans = [Span(60, 120), Span(125, 185)]
        got = round_labels(spans, 5)
        self.assertEqual(len(got), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
